import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.1lR7qgqY.js";const c=JSON.parse('{"title":"M6 可觀測, 稽核與評估","description":"","frontmatter":{},"headers":[],"relativePath":"build/m6-observability.md","filePath":"build/m6-observability.md","lastUpdated":null}'),o={name:"build/m6-observability.md"};function d(i,t,s,n,h,p){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="m6-可觀測-稽核與評估" tabindex="-1">M6 可觀測, 稽核與評估 <a class="header-anchor" href="#m6-可觀測-稽核與評估" aria-label="Permalink to &quot;M6 可觀測, 稽核與評估&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要 (測試集); ○ 依情境 (追蹤平台)</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: promptfoo 實際設定語法與收購案完成日期; OpenTelemetry GenAI 語意規範的最新狀態</li></ul></div><p><strong>結論</strong>: 初階讀者不需要追蹤平台, 需要的是一份 30 至 100 題的固定測試集. 每次換模型, 換提示或升級元件時跑一次, 就能回答「變好還是變壞」(信心: 高). 多人共用之後, 再加上可觀測與稽核平台, 記錄誰在什麼時候讓 AI 做了什麼.</p><p><strong>這一塊在圖上的位置</strong>: VM 稽核區的 Langfuse, OTel Collector, Prometheus, 以及既有 SIEM. <strong>前置模組</strong>: M5. <strong>完成後的狀態</strong>: 每次換模型或升級都能用測試集比較結果; 每次模型與工具呼叫都留下紀錄.</p><h2 id="m6-1-30-至-100-題測試集的設計" tabindex="-1">M6.1 30 至 100 題測試集的設計 <a class="header-anchor" href="#m6-1-30-至-100-題測試集的設計" aria-label="Permalink to &quot;M6.1 30 至 100 題測試集的設計&quot;">​</a></h2><p>最少需要三件事:</p><ol><li>一份固定測試集, 每題含「問題」與「期望答案或關鍵字」.</li><li>保留介面的對話紀錄.</li><li>記錄每次變更的版本 (見 O2).</li></ol><p>測試集的組成建議:</p><table tabindex="0"><thead><tr><th>類型</th><th>題數</th><th>用途</th></tr></thead><tbody><tr><td>日常任務題</td><td>10 至 30</td><td>確認基本功能沒有退步</td></tr><tr><td>檢索問答題</td><td>50 (M4.3 節)</td><td>確認檢索命中率</td></tr><tr><td>工具呼叫題</td><td>10 至 20</td><td>確認函式呼叫格式正確 (K5)</td></tr><tr><td>邊界與安全題</td><td>5 至 10</td><td>確認拒答與權限邊界</td></tr></tbody></table><p>T2 微調後的驗證, 沿用同一份測試集.</p><h2 id="m6-2-promptfoo-實作" tabindex="-1">M6.2 promptfoo 實作 <a class="header-anchor" href="#m6-2-promptfoo-實作" aria-label="Permalink to &quot;M6.2 promptfoo 實作&quot;">​</a></h2><p>promptfoo 是命令列工具, 不需要常駐服務, 採 MIT 授權. OpenAI 於 2026-03-09 宣布收購, 官方聲明 &quot;remains open source under MIT&quot; (來源: 研究 2 引用之官方聲明). 收購案的完成日期未能確認; 長期所有權變動屬鎖定風險, 須持續追蹤 (信心: 中).</p><p>設定檔語法會隨版本變動, 本章不放未經核對的範例, 實作步驟待依官方文件逐步驗證後補上.</p><h2 id="m6-3-追蹤平台何時值得裝" tabindex="-1">M6.3 追蹤平台何時值得裝 <a class="header-anchor" href="#m6-3-追蹤平台何時值得裝" aria-label="Permalink to &quot;M6.3 追蹤平台何時值得裝&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>授權 / 狀態</th><th>自架資源</th></tr></thead><tbody><tr><td>Langfuse</td><td>MIT; ClickHouse 公司於 2026-01-16 收購, 授權維持不變 (coverge.ai)</td><td>v3 起強制需要 ClickHouse, Redis, PostgreSQL, S3 / MinIO, 共 6 個服務; 官方最低需求為 ClickHouse 2 CPU / 8GiB, Redis 1 CPU / 1.5GiB (Langfuse 官方擴充文件)</td></tr><tr><td>Arize Phoenix</td><td>Elastic License 2.0 (非 OSI); Dynatrace 於 2026-10 初完成收購 Arize</td><td>比 Langfuse 輕 (訓練資料內資訊, 可能已過時)</td></tr><tr><td>Ragas</td><td>Apache 2.0; 0.4.3 (2026-01-13)</td><td>函式庫</td></tr><tr><td>DeepEval</td><td>Apache 2.0; 4.3.1 (2026-10-16)</td><td>函式庫</td></tr></tbody></table><p>Langfuse 光 ClickHouse 最低就要 8GiB, 會與模型搶記憶體, 因此對硬體等級 A 至 D 不划算 (信心: 高, 依官方最低需求推論). 多人環境且有專人維運時, 才值得評估.</p><h2 id="m6-4-可觀測與稽核平台" tabindex="-1">M6.4 可觀測與稽核平台 <a class="header-anchor" href="#m6-4-可觀測與稽核平台" aria-label="Permalink to &quot;M6.4 可觀測與稽核平台&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>Langfuse: 記錄提示, 回應, token 數, 延遲與代理每一步; 存放完整對話, 須設定存取權限與保存期限</li><li>OpenTelemetry (OTel): 以 OTLP 格式蒐集紀錄, 由 Collector 轉送到 Langfuse 與既有 SIEM; Langfuse 只接收 HTTP 版的 OTLP</li><li>Prometheus 與 Grafana: 抓取 vLLM 與 llama-server 的 <code>/metrics</code>, 畫成儀表板並設定警示; Ollama 沒有原生指標, 改在閘道層蒐集</li></ul><h2 id="m6-5-驗收測試" tabindex="-1">M6.5 驗收測試 <a class="header-anchor" href="#m6-5-驗收測試" aria-label="Permalink to &quot;M6.5 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>一次對話能在 Langfuse 看到完整軌跡</li><li>閘道與政策判定的紀錄能在 SIEM 查到</li><li>延遲超過門檻時, 警示能送達維運人員</li></ul>',22)])])}const m=e(o,[["render",d]]);export{c as __pageData,m as default};
